// Relative URLs are not resolvable in Server Components, so resolve against a base URL.
const API_BASE_URL = process.env.API_BASE_URL ?? 'http://localhost:3000'

async function fetchJson(path: string) {
  const res = await fetch(`${API_BASE_URL}${path}`)
  if (!res.ok) throw new Error(`Request to ${path} failed: ${res.status}`)
  return res.json()
}

// Parallel data fetching: all three requests start at the same time
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetchJson('/api/analytics'),
      fetchJson('/api/notifications'),
      fetchJson('/api/settings'),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { pageViews: 1000, visitors: 250 },
      notifications: [{ id: 1, message: 'Welcome to your dashboard' }],
      settings: { theme: 'light', language: 'en' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Page views: {analytics.pageViews}</p>
        <p>Visitors: {analytics.visitors}</p>
      </section>

      <section>
        <h3>Notifications ({notifications.length})</h3>
        <ul>
          {notifications.map((n: { id: number; message: string }) => (
            <li key={n.id}>{n.message}</li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Language: {settings.language}</p>
      </section>
    </div>
  )
}

